create table if not exists public.flashcard_decks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,course_id uuid references public.courses(id) on delete set null,title text not null,topic text not null default '',created_at timestamptz not null default now());
create index if not exists flashcard_decks_user_created_idx on public.flashcard_decks(user_id,created_at desc);
alter table public.flashcard_decks enable row level security;
revoke all on public.flashcard_decks from anon;
grant select,insert,update,delete on public.flashcard_decks to authenticated;
create policy "Students manage their own flashcard decks" on public.flashcard_decks for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id and (course_id is null or exists(select 1 from public.courses c where c.id=course_id and c.user_id=(select auth.uid()))));
create table if not exists public.flashcards(id uuid primary key default gen_random_uuid(),deck_id uuid not null references public.flashcard_decks(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,front text not null,back text not null,position integer not null default 0,created_at timestamptz not null default now());
create index if not exists flashcards_deck_position_idx on public.flashcards(deck_id,position);
alter table public.flashcards enable row level security;
revoke all on public.flashcards from anon;
grant select,insert,update,delete on public.flashcards to authenticated;
create policy "Students manage their own flashcards" on public.flashcards for all to authenticated using ((select auth.uid())=user_id and exists(select 1 from public.flashcard_decks d where d.id=deck_id and d.user_id=(select auth.uid()))) with check ((select auth.uid())=user_id and exists(select 1 from public.flashcard_decks d where d.id=deck_id and d.user_id=(select auth.uid())));
